mapper.select:
select `identify_id` from (select count(1) as `number`,`identify_id` from `parking_access_record`
`access_time` between #{date.startTime} and #{date.endTime}
group by `identify_id` having count(1) = #{number}) a

SELECT
COUNT(CASE WHEN `access_type` = 'ACCESS_IN' THEN 1 END) AS `inNum`,
COUNT(CASE WHEN `access_type` = 'ACCESS_OUT' THEN 1 END) AS `outNum`
FROM `parking_access_record`


        and `access_time` >= #{param.period.begin}


        and `access_time` <= #{param.period.end}
